contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address proposedAddress) public payable {
        uint beforeCount = c.proposalCount(); if (__ESBMC_reverted()) return;
        c.newAddressProposal(proposedAddress, "X"); if (__ESBMC_reverted()) return;
        uint afterCount = c.proposalCount(); if (__ESBMC_reverted()) return;
        require(afterCount == beforeCount + 1, "proposalCount must increase by one");
        address stored = c.mapPID_address(afterCount); if (__ESBMC_reverted()) return;
        assert(stored == proposedAddress);
    }

    receive() external payable {}
}

